function margin(price, cost){ if(!(price>0)) return NaN; return (price-cost)/price; }
function markup(price, cost){ if(!(cost>0)) return NaN; return (price-cost)/cost; }
function costFromMargin(price, m){ if(!(price>0)) return NaN; return price*(1-m); }
function costFromMarkup(price, mk){ if(!(mk>-1)) return NaN; return price/(1+mk); }
function priceFromMargin(cost, m){ if(!(m<1)) return NaN; return cost/(1-m); }
var EXPORTS = { margin:margin, markup:markup, costFromMargin:costFromMargin, costFromMarkup:costFromMarkup, priceFromMargin:priceFromMargin };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MarginForgePure = EXPORTS; }
